import { Injectable, OnDestroy, TemplateRef } from '@angular/core';
import { BehaviorSubject, Observable, Subject, combineLatest, takeUntil } from 'rxjs';
import { QTablePaginationMode } from './types/table-pagination-mode.type';
import { QTableSortOperator } from './types/table-sort-operator.interface';

@Injectable()
export class QTableService implements OnDestroy {
  tableData$: Observable<unknown[]>;
  currentPage$: Observable<number>;
  pageSize$: Observable<number>;
  theadTemplate$: Observable<TemplateRef<unknown>>;
  sortOperator$: Observable<QTableSortOperator | null>;
  currentPageData$: Observable<unknown[]>;
  columnCount$: Observable<number>;

  private _tableDataSubject = new BehaviorSubject<unknown[]>([]);
  private _currentPageSubject = new BehaviorSubject<number>(1);
  private _pageSizeSubject = new BehaviorSubject<number>(25);
  private _theadTemplateSubject = new Subject<TemplateRef<unknown>>();
  private _sortOperatorSubject = new BehaviorSubject<QTableSortOperator | null>(null);
  private _currentPageDataSubject = new BehaviorSubject<unknown[]>([]);
  private _columnCountSubject = new BehaviorSubject<number>(1);
  private _totalItems = new BehaviorSubject<number>(0);
  private _paginationMode: QTablePaginationMode = 'client';
  private _destroy$ = new Subject<void>();

  constructor() {
    this.tableData$ = this._tableDataSubject.asObservable();
    this.currentPage$ = this._currentPageSubject.asObservable();
    this.pageSize$ = this._pageSizeSubject.asObservable();
    this.theadTemplate$ = this._theadTemplateSubject.asObservable();
    this.sortOperator$ = this._sortOperatorSubject.asObservable();
    this.currentPageData$ = this._currentPageDataSubject.asObservable();
    this.columnCount$ = this._columnCountSubject.asObservable();

    combineLatest([this.tableData$, this.currentPage$, this.pageSize$, this.sortOperator$])
      .pipe(takeUntil(this._destroy$))
      .subscribe(([tableData, currentPage, pageSize, sortOperator]) => {
        const dataClone = tableData?.slice();
        if (this._paginationMode === 'client' && !!dataClone) {
          if (sortOperator?.sortFn && sortOperator?.sortOrder) {
            const { sortFn, sortOrder, columnKey } = sortOperator;
            this._currentPageDataSubject.next(
              this._calcCurrentPageData(
                dataClone.sort((a: unknown, b: unknown) =>
                  sortFn
                    ? sortFn(
                        (a as { [key: string]: unknown })[columnKey],
                        (b as { [key: string]: unknown })[columnKey],
                        sortOrder,
                      )
                    : 0,
                ),
                currentPage,
                pageSize,
              ),
            );
          } else {
            this._currentPageDataSubject.next(
              this._calcCurrentPageData(dataClone, currentPage, pageSize),
            );
          }
        } else if (this._paginationMode === 'server') {
          this._currentPageDataSubject.next(tableData);
        }
      });
  }

  ngOnDestroy(): void {
    this._destroy$.next();
    this._destroy$.complete();
  }

  updateColumnCount(columnCount: number): void {
    this._columnCountSubject.next(columnCount);
  }

  updateSortOperator(sortOperator: QTableSortOperator): void {
    this._sortOperatorSubject.next(sortOperator);
  }

  updateCurrentPage(pageIndex: number): void {
    this._currentPageSubject.next(pageIndex);
  }

  updatePageSize(pageSize: number): void {
    this._pageSizeSubject.next(pageSize);
  }

  setTheadTemplate(template: TemplateRef<unknown>): void {
    this._theadTemplateSubject.next(template);
  }

  updateTableData(data: unknown[]): void {
    this._tableDataSubject.next(data);
  }

  updateTotalItems(totalItems: number): void {
    this._totalItems.next(totalItems);
  }

  setPaginationMode(mode: QTablePaginationMode): void {
    this._paginationMode = mode;
  }

  private _calcCurrentPageData(data: unknown[], currentPage: number, pageSize: number): unknown[] {
    return data?.slice((currentPage - 1) * pageSize, currentPage * pageSize) || [];
  }
}
