import { NgFor, NgIf, NgTemplateOutlet } from '@angular/common';
import {
  ChangeDetectionStrategy,
  Component,
  HostBinding,
  Input,
  TemplateRef,
  ViewEncapsulation,
  booleanAttribute,
  inject,
} from '@angular/core';
import { QIconComponent, QIconRegistryService } from '@questrade/allspark-angular-components/icon';
import { QSpinnerComponent } from '@questrade/allspark-angular-components/spinner';
import { infoOutline } from '@questrade/allspark-icons/icons';
import { error128 } from '@questrade/allspark-icons/illustrations-128';
import { QTableLayout } from '../types/table-layout.type';

type QTableContentState = 'loading' | 'error' | 'empty' | null;

@Component({
  selector: 'table[q-table-content]',
  imports: [NgIf, NgFor, NgTemplateOutlet, QSpinnerComponent, QIconComponent],
  templateUrl: './table-content.component.html',
  styleUrls: ['./table-content.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  host: {
    class: 'q-table-content',
    '[style.table-layout]': 'tableLayout',
    '[style.width]': 'scrollX',
    '[style.min-width]': "scrollX ? '100%': null",
    '[style.max-height]': "scrollY ? '100%': null",
  },
})
export class QTableContentComponent {
  @Input() tableLayout: QTableLayout = 'auto';
  @Input() theadTemplate: TemplateRef<unknown> | null = null;
  @Input() contentTemplate: TemplateRef<unknown> | null = null;
  @Input() listOfColWidth: readonly (string | null)[] = [];
  @Input() scrollX: string | null = null;
  @Input() scrollY: string | null = null;
  @Input({ transform: booleanAttribute }) loading = false;
  @Input({ transform: booleanAttribute }) errorState = false;
  @Input({ transform: booleanAttribute }) empty = false;
  @Input({ transform: booleanAttribute }) showEmptyStateIcon = false;
  @Input() errorStateTitle = '';
  @Input() errorStateDescription = '';
  @Input() emptyStateTitle = '';
  @Input() emptyStateDescription = '';
  @Input() emptyStateButton: TemplateRef<unknown> | null = null;
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-table-content';

  private readonly _iconRegistryService = inject(QIconRegistryService);

  get currentState(): QTableContentState {
    if (this.loading) return 'loading';
    if (this.errorState) return 'error';
    if (this.empty) return 'empty';
    return null;
  }

  constructor() {
    this._iconRegistryService.registerIcons([infoOutline, error128]);
  }
}
