import { NgIf, NgTemplateOutlet } from '@angular/common';
import {
  AfterContentInit,
  AfterViewInit,
  ChangeDetectionStrategy,
  Component,
  ContentChildren,
  ElementRef,
  HostBinding,
  Input,
  OnInit,
  QueryList,
  Renderer2,
  TemplateRef,
  ViewChild,
  ViewEncapsulation,
  inject,
} from '@angular/core';
import { QDestroyService } from '@questrade/allspark-angular-components/core/services';
import { merge, takeUntil } from 'rxjs';
import { QTableHeaderCellComponent } from '../cell/header-cell/table-header-cell.component';
import { QTableService } from '../table.service';

@Component({
  // eslint-disable-next-line @angular-eslint/component-selector
  selector: 'thead:not(.q-table-thead)',
  templateUrl: './table-header.component.html',
  styleUrls: ['./table-header.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [NgIf, NgTemplateOutlet],
  providers: [QDestroyService],
  encapsulation: ViewEncapsulation.None,
})
export class QTableHeaderComponent implements OnInit, AfterContentInit, AfterViewInit {
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-table-header';

  @ContentChildren(QTableHeaderCellComponent, { descendants: true })
  _listOfQHeaderCellComponent!: QueryList<QTableHeaderCellComponent>;

  @ViewChild('contentTemplate', { static: true }) _templateRef!: TemplateRef<unknown>;

  @HostBinding('class') hostClass = 'q-table-header';

  _isInsideTable = false;

  private readonly _tableService: QTableService = inject(QTableService);
  private readonly _elementRef: ElementRef = inject(ElementRef);
  private readonly _renderer: Renderer2 = inject(Renderer2);
  private readonly _destroy$ = inject(QDestroyService);

  constructor() {
    this._isInsideTable = !!this._tableService;
  }

  ngOnInit(): void {
    if (this._isInsideTable) {
      this._tableService.setTheadTemplate(this._templateRef);
    }
  }

  ngAfterContentInit(): void {
    this._subscribeToSortUpdates();
  }

  ngAfterViewInit(): void {
    this._removeHeaderInsideTable();
  }

  private _subscribeToSortUpdates(): void {
    const manualSort$ = merge(
      ...this._listOfQHeaderCellComponent.map((th) => th.clickSubject$),
    ).pipe(takeUntil(this._destroy$));

    manualSort$.subscribe((data: QTableHeaderCellComponent) => {
      this._listOfQHeaderCellComponent.forEach((th) => {
        if (th === data) {
          this._tableService.updateSortOperator({
            columnKey: th.columnKey,
            sortFn: th.sortFn,
            sortOrder: th.sortOrder,
          });
        } else {
          th.clearSortOrder();
        }
      });
    });
  }

  private _removeHeaderInsideTable(): void {
    if (this._isInsideTable) {
      this._renderer.removeChild(
        this._renderer.parentNode(this._elementRef.nativeElement),
        this._elementRef.nativeElement,
      );
    }
  }
}
