import { NgIf } from '@angular/common';
import {
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  EventEmitter,
  HostBinding,
  HostListener,
  Input,
  Output,
  ViewEncapsulation,
  booleanAttribute,
  inject,
} from '@angular/core';
import { ENTER, SPACE } from '@questrade/allspark-angular-components/core/utils';
import { Subject } from 'rxjs';
import { QTableSortFn } from '../../types/table-sort-function.type';
import { QTableSortOrder } from '../../types/table-sort-order.type';
import { QTableSorterComponent } from '../table-sorter/table-sorter.component';

@Component({
  selector: 'th[q-table-cell]',
  imports: [NgIf, QTableSorterComponent],
  templateUrl: './table-header-cell.component.html',
  styleUrls: ['./table-header-cell.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  host: {
    class: 'q-note',
    '[class.q-table-sortable]': '!!sortFn || isSortable',
    '[attr.tabIndex]': '!!sortFn || isSortable ? "0" : "-1"',
  },
})
export class QTableHeaderCellComponent<T = unknown> {
  @Output() readonly sortChanged = new EventEmitter<QTableSortOrder>();

  @Input() sortOrder: QTableSortOrder | null = null;
  @Input() sortFn: QTableSortFn<T> | null = null;
  @Input() columnKey = '';
  @Input({ transform: booleanAttribute }) isSortable = false;
  @Input() @HostBinding('attr.data-qt') get dataQt(): string {
    return `q-table-header-cell-${this.columnKey}`;
  }

  @HostListener('click') _onClick = (): void => this._updateSortOrder();
  @HostListener('keydown', ['$event']) _onKeyDown = ({ code }: KeyboardEvent): void =>
    this._sortUpdateOnKeyCodeMatch(code);

  clickSubject$ = new Subject<QTableHeaderCellComponent<T>>();

  private readonly _cdr = inject(ChangeDetectorRef);

  clearSortOrder(): void {
    if (this.sortOrder !== null) {
      this.sortOrder = null;
      this._cdr.markForCheck();
    }
  }

  private _sortUpdateOnKeyCodeMatch(code: string): void {
    if ([ENTER, SPACE].includes(code)) {
      this._updateSortOrder();
    }
  }

  private _updateSortOrder(): void {
    if (!this.sortFn && !this.isSortable) return;

    switch (this.sortOrder) {
      case 'ascend':
        this.sortOrder = 'descend';
        break;
      case 'descend':
        this.sortOrder = null;
        break;
      default:
        this.sortOrder = 'ascend';
        break;
    }
    this.clickSubject$.next(this);
    this.sortChanged.emit(this.sortOrder);
  }
}
