import {
  ChangeDetectionStrategy,
  Component,
  EventEmitter,
  HostBinding,
  Input,
  Output,
  ViewEncapsulation,
  booleanAttribute,
} from '@angular/core';
import { QExpansionTriggerComponent } from '@questrade/allspark-angular-components/core/components';

@Component({
  // eslint-disable-next-line @angular-eslint/component-selector
  selector: 'span[qExpand]',
  imports: [QExpansionTriggerComponent],
  template: `
    <q-expansion-trigger
      class="q-expansion-icon"
      [active]="qExpand"
      (activeChange)="onExpandChange()" />
    <ng-content />
  `,
  styleUrls: ['./table-data-cell.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
})
export class QExpandComponent {
  @Output() readonly qExpandChange = new EventEmitter<boolean>();

  @Input({ transform: booleanAttribute }) qExpand = false;

  @HostBinding('class') hostClass = 'q-expand';

  @HostBinding('class') get hostClasses(): string {
    return ['q-expand', this.qExpand && 'q-table-row-expanded'].filter(Boolean).join(' ');
  }
  @HostBinding('attr.data-qt') dataQt = 'q-expand';

  onExpandChange(): void {
    this.qExpand = !this.qExpand;
    this.qExpandChange.emit(this.qExpand);
  }
}
