import { AsyncPipe } from '@angular/common';
import {
  ChangeDetectionStrategy,
  Component,
  HostBinding,
  Input,
  ViewEncapsulation,
  inject,
} from '@angular/core';
import { accordionAnimations } from '@questrade/allspark-angular-components/core/animations';
import { QTableService } from '../table.service';

@Component({
  // eslint-disable-next-line @angular-eslint/component-selector
  selector: 'tr[qExpand]',
  imports: [AsyncPipe],
  template: `
    <td [colSpan]="_tableService.columnCount$ | async">
      <div
        class="q-expand-cell-container"
        [@bodyExpansion]="qExpand ? 'expanded' : 'collapsed'"
        (@bodyExpansion.done)="_onAnimationDone()">
        <ng-content />
      </div>
    </td>
  `,
  animations: [accordionAnimations.bodyExpansion],
  styleUrls: ['./table-row.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
})
export class QTableRowExpandComponent {
  @Input() get qExpand(): boolean {
    return this._qExpand;
  }
  set qExpand(value: boolean) {
    this._qExpand = value;

    if (this._qExpand) {
      this._hidden = false;
    }
  }

  @HostBinding('class') hostClass = 'q-table-row-expand';
  @HostBinding('attr.data-qt') dataQt = 'q-table-row-expand';
  @HostBinding('attr.hidden') get hidden(): boolean | null {
    return this._hidden || null;
  }

  readonly _tableService = inject(QTableService);

  private _qExpand = false;
  private _hidden = true;

  _onAnimationDone(): void {
    if (!this.qExpand) {
      this._hidden = true;
    }
  }
}
