import {
  ChangeDetectionStrategy,
  Component,
  ContentChildren,
  ElementRef,
  HostBinding,
  Input,
  OnInit,
  QueryList,
  Renderer2,
  ViewEncapsulation,
  inject,
} from '@angular/core';
import { QTableDataCellComponent } from '../cell/data-cell/table-data-cell.component';

@Component({
  selector: 'tr[q-table-row]',
  template: `<ng-content />`,
  styleUrls: ['./table-row.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
})
export class QTableRowComponent implements OnInit {
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-table-row';

  @ContentChildren(QTableDataCellComponent, { descendants: true })
  columns!: QueryList<QTableDataCellComponent>;

  @HostBinding('class') hostClass = 'q-table-row';

  _isInsideHeader = false;

  private readonly _renderer: Renderer2 = inject(Renderer2);
  private readonly _elementRef: ElementRef = inject(ElementRef);

  ngOnInit(): void {
    this._isInsideHeader = !this._renderer.parentNode(this._elementRef.nativeElement);
  }
}
