import { NgIf, NgTemplateOutlet } from '@angular/common';
import {
  ChangeDetectionStrategy,
  Component,
  HostBinding,
  inject,
  Input,
  TemplateRef,
  ViewEncapsulation,
} from '@angular/core';
import { QIconComponent, QIconRegistryService } from '@questrade/allspark-angular-components/icon';
import { arrowBack } from '@questrade/allspark-icons/icons';
import { QTableSortOrder } from '../../types/table-sort-order.type';

@Component({
  selector: 'q-table-sorter',
  imports: [NgIf, NgTemplateOutlet, QIconComponent],
  templateUrl: './table-sorter.component.html',
  styleUrls: ['./table-sorter.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
})
export class QTableSorterComponent {
  @Input() sortOrder: QTableSortOrder | null = null;
  @Input() contentTemplate: TemplateRef<unknown> | null = null;
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-table-sorter';

  @HostBinding('class') get hostClasses(): string {
    return `q-table-sorter ${this.sortOrder ? `q-table-sorter-${this.sortOrder}` : ''}`;
  }

  private readonly _iconRegistryService = inject(QIconRegistryService);

  constructor() {
    this._iconRegistryService.registerIcons([arrowBack]);
  }
}
