import { coerceNumberProperty } from '@angular/cdk/coercion';
import { NgIf } from '@angular/common';
import {
  AfterViewInit,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  ContentChildren,
  ElementRef,
  EventEmitter,
  HostBinding,
  Input,
  NgZone,
  OnInit,
  Output,
  QueryList,
  TemplateRef,
  ViewChild,
  ViewEncapsulation,
  booleanAttribute,
  inject,
} from '@angular/core';
import { QScrollShadowDirective } from '@questrade/allspark-angular-components/core/directives';
import { QDestroyService } from '@questrade/allspark-angular-components/core/services';
import {
  Subject,
  delay,
  distinctUntilChanged,
  fromEvent,
  startWith,
  switchMap,
  takeUntil,
} from 'rxjs';
import { QTableFooterComponent } from './footer/table-footer.component';
import { QTableRowComponent } from './row/table-row.component';
import { QTableContentComponent } from './table-content/table-content.component';
import { QTableService } from './table.service';
import { QTableLayout } from './types/table-layout.type';
import { QTablePaginationMode } from './types/table-pagination-mode.type';
import { QTablePaginationType } from './types/table-pagination.type';

type QTableCellExpandType = { id?: number | string; expanded?: boolean };

@Component({
  selector: 'q-table',
  imports: [NgIf, QTableContentComponent, QScrollShadowDirective, QTableFooterComponent],
  templateUrl: './table.component.html',
  styleUrls: ['./table.component.scss'],
  providers: [QTableService, QDestroyService],
  encapsulation: ViewEncapsulation.None,
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class QTableComponent<T = unknown> implements OnInit, AfterViewInit {
  @Output() readonly pageSizeChanged = new EventEmitter<number>();
  @Output() readonly pageNumberChanged = new EventEmitter<number>();
  @Output() readonly hitBottom = new EventEmitter<boolean>();

  @Input() paginationType: QTablePaginationType = 'button';
  @Input() tableLayout: QTableLayout = 'auto';
  @Input() listOfColWidth: readonly (string | null)[] = [];
  @Input({ transform: booleanAttribute }) showFooter = false;
  @Input({ transform: booleanAttribute }) infiniteLoading = false;
  @Input({ transform: booleanAttribute }) flexScroll = false;
  @Input({ transform: booleanAttribute }) loading = false;
  @Input({ transform: booleanAttribute }) errorState = false;
  @Input({ transform: booleanAttribute }) showEmptyStateIcon = false;
  @Input({ transform: booleanAttribute }) roundedCorners = false;
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-table';
  @Input() errorStateTitle = '';
  @Input() errorStateDescription = '';
  @Input() emptyStateTitle = '';
  @Input() emptyStateDescription = '';
  @Input() scrollY: string | null = null;
  @Input() scrollX: string | null = null;

  @Input() get totalItems(): number {
    return this._totalItems;
  }
  set totalItems(value: number) {
    this._totalItems = coerceNumberProperty(value, 0);
    this._tableService.updateTotalItems(coerceNumberProperty(value, 0));
  }

  @Input() get tableData(): T[] {
    return this._tableData;
  }
  set tableData(value: T[]) {
    this._tableData = value;
    this._tableService.updateTableData(value);
  }

  @Input() get currentPage(): number {
    return this._currentPage;
  }
  set currentPage(value: number) {
    this._tableService.updateCurrentPage(value);
    this._currentPage = value;
  }

  @Input() get pageSize(): number {
    return this._pageSize;
  }
  set pageSize(value: number) {
    this._tableService.updatePageSize(value);
    this._pageSize = value;
  }

  @Input() get paginationMode(): QTablePaginationMode {
    return this._paginationMode;
  }
  set paginationMode(value: QTablePaginationMode) {
    this._paginationMode = value;
    this._tableService.setPaginationMode(value);
  }

  @ContentChildren(QTableRowComponent, { descendants: true })
  _trList!: QueryList<QTableRowComponent>;

  @ViewChild('tableHeaderElement', { read: ElementRef }) _tableHeaderElement!: ElementRef;
  @ViewChild('tableBodyElement', { read: ElementRef }) _tableBodyElement!: ElementRef;

  currentTableData: T[] = [];
  theadTemplate: TemplateRef<unknown> | null = null;
  columnCount = 0;

  private _tableData: T[] = [];
  private _totalItems = 0;
  private _currentPage = 1;
  private _pageSize = 25;
  private _scroll$ = new Subject<void>();
  private _paginationMode: QTablePaginationMode = 'client';
  private readonly _tableService = inject(QTableService);
  private readonly _cdr = inject(ChangeDetectorRef);
  private readonly _ngZone = inject(NgZone);
  private readonly _destroy$ = inject(QDestroyService);

  ngOnInit(): void {
    this._registerTableServiceSubscriptions();
  }

  ngAfterViewInit(): void {
    this._synchronizeHorizontalScroll();
    this._triggerInfiniteScroll();
    this._updateColumnCount();
    this._trList.changes.pipe(takeUntil(this._destroy$)).subscribe(() => {
      this._updateColumnCount();
    });
  }

  /**
   * Expand or collapse all rows
   * @param {boolean} expand - Expand or collapse all.
   */
  expandAllRows(expand: boolean): void {
    this.currentTableData.forEach((item: T) => {
      (item as QTableCellExpandType).expanded = expand;
    });
  }

  /**
   * Collapse all rows but expanded one
   * @param {boolean} expanded - Expand state of a row, no logic will be performed if a row was collapsed.
   * @param {string | number} expandedItemId - Expanded row item unique id, so we know which item to keep expanded.
   */
  collapseOtherRows(expanded: boolean, expandedItemId: string | number): void {
    if (!expanded) return;

    this.currentTableData.forEach((item: T) => {
      const currentRow = item as QTableCellExpandType;
      if (currentRow.id !== expandedItemId) {
        currentRow.expanded = false;
      }
    });
  }

  get isEmpty(): boolean {
    return !this._tableData.length;
  }

  get hasFooter(): boolean {
    return this.showFooter && !this.loading && !this.errorState && !this.isEmpty;
  }

  private _registerTableServiceSubscriptions(): void {
    const { theadTemplate$, currentPageData$, pageSize$, currentPage$ } = this._tableService;

    currentPageData$.pipe(takeUntil(this._destroy$)).subscribe((tableData: unknown[]) => {
      this.currentTableData = tableData as T[];
      this._cdr.markForCheck();
    });

    theadTemplate$.pipe(takeUntil(this._destroy$)).subscribe((theadTemplate) => {
      this.theadTemplate = theadTemplate;
      this._cdr.markForCheck();
    });

    pageSize$.pipe(takeUntil(this._destroy$)).subscribe((pageSize) => {
      this._pageSize = pageSize;
      this.pageSizeChanged.emit(pageSize);
      this._cdr.markForCheck();
    });

    currentPage$.pipe(takeUntil(this._destroy$)).subscribe((pageNumber) => {
      this._currentPage = pageNumber;
      this.pageNumberChanged.emit(pageNumber);
      this._cdr.markForCheck();
    });
  }

  private _synchronizeHorizontalScroll(): void {
    if (!this.scrollX) return;
    this._ngZone.runOutsideAngular(() => {
      const scrollBodyEvent$ = this._scroll$.pipe(
        startWith(null),
        delay(0),
        switchMap(() =>
          fromEvent<MouseEvent>(this._tableBodyElement?.nativeElement, 'scroll').pipe(
            startWith(true),
          ),
        ),
        takeUntil(this._destroy$),
      );

      const scrollHeaderEvent$ = this._scroll$.pipe(
        startWith(null),
        delay(0),
        switchMap(() =>
          fromEvent<MouseEvent>(this._tableHeaderElement?.nativeElement, 'scroll').pipe(
            startWith(true),
          ),
        ),
        takeUntil(this._destroy$),
      );

      scrollBodyEvent$.subscribe(() => {
        this._tableHeaderElement.nativeElement.scrollLeft =
          this._tableBodyElement?.nativeElement.scrollLeft;
      });

      scrollHeaderEvent$.subscribe(() => {
        this._tableBodyElement.nativeElement.scrollLeft =
          this._tableHeaderElement?.nativeElement.scrollLeft;
      });
    });
  }

  private _triggerInfiniteScroll(): void {
    if (this.paginationType !== 'infinite' || !this.scrollY) return;

    this._ngZone.runOutsideAngular(() => {
      fromEvent(this._tableBodyElement?.nativeElement, 'scroll')
        .pipe(delay(0), takeUntil(this._destroy$), distinctUntilChanged())
        .subscribe(() => {
          const { clientHeight, scrollHeight, scrollTop } = this._tableBodyElement
            ?.nativeElement as HTMLElement;

          const hitTheBottom = scrollTop + clientHeight === scrollHeight;

          if (hitTheBottom) {
            const newPageSize = this.pageSize + Math.min(this.tableData.length - this.pageSize, 25);
            this._tableService.updatePageSize(newPageSize);
            this.hitBottom.emit(true);
          }
        });
    });
  }

  private _updateColumnCount(): void {
    const maxColumnCount = Math.max(...this._trList.map((row) => row.columns.length));
    this.columnCount = maxColumnCount;
    this._tableService.updateColumnCount(maxColumnCount);
  }
}
