import { NgIf, NgSwitch, NgSwitchCase, NgSwitchDefault } from '@angular/common';
import {
  ChangeDetectionStrategy,
  Component,
  HostBinding,
  Input,
  OnInit,
  ViewEncapsulation,
  booleanAttribute,
  inject,
  numberAttribute,
} from '@angular/core';
import { TranslocoModule } from '@jsverse/transloco';
import { QChipComponent } from '@questrade/allspark-angular-components/chip';
import { QIconRegistryService } from '@questrade/allspark-angular-components/icon';
import { QPaginatorComponent } from '@questrade/allspark-angular-components/paginator';
import { QSpinnerComponent } from '@questrade/allspark-angular-components/spinner';
import {
  ALLSPARK_SCOPE,
  MISSING_KEY_HANDLER,
} from '@questrade/allspark-angular-components/transloco';
import { add } from '@questrade/allspark-icons/icons';
import { QTableService } from '../table.service';
import { QTablePaginationType } from '../types/table-pagination.type';

@Component({
  selector: 'q-table-footer',
  imports: [
    TranslocoModule,
    NgIf,
    NgSwitch,
    NgSwitchCase,
    NgSwitchDefault,
    QPaginatorComponent,
    QSpinnerComponent,
    QChipComponent,
  ],
  providers: [MISSING_KEY_HANDLER, ALLSPARK_SCOPE],
  templateUrl: './table-footer.component.html',
  styleUrls: ['./table-footer.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
})
export class QTableFooterComponent implements OnInit {
  @Input() paginationType: QTablePaginationType = 'button';
  @Input({ transform: numberAttribute }) totalItems = 0;
  @Input({ transform: numberAttribute }) currentPage = 1;
  @Input({ transform: numberAttribute }) pageSize = 25;
  @Input({ transform: booleanAttribute }) infiniteLoading = false;
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-table-footer';
  @Input({ transform: booleanAttribute })
  @HostBinding('class.q-table-footer-rounded-corners')
  roundedCorners = false;

  readonly rootClass = 'q-table-footer';

  private _initialBatchSize = 0;
  private readonly _tableService = inject(QTableService);
  private readonly _iconRegistry = inject(QIconRegistryService);

  ngOnInit(): void {
    this._initialBatchSize = this.pageSize;
    this._iconRegistry.registerIcon(add);
  }

  _onPageChanged(page: number): void {
    this.currentPage = page;
    this._tableService.updateCurrentPage(page);
  }

  _increasePageSize(): void {
    const newPageSize = this.pageSize + this.nextBatchSize;
    this.pageSize = newPageSize;
    this._tableService.updatePageSize(newPageSize);
  }

  _getTranslationPluralization(): string {
    const translateSlice = 'allspark.table.footer.';

    if (this.totalItems === 0) {
      return `${translateSlice}showingZero`;
    } else if (this.totalItems === 1) {
      return `${translateSlice}showingOne`;
    } else {
      return `${translateSlice}showingMultiple`;
    }
  }

  get nextBatchSize(): number {
    return this.totalItems > this.pageSize
      ? Math.min(this.totalItems - this.pageSize, this._initialBatchSize)
      : this.totalItems;
  }
}
