import { NgSwitch, NgSwitchCase } from '@angular/common';
import {
  ChangeDetectionStrategy,
  Component,
  HostBinding,
  Input,
  ViewEncapsulation,
  booleanAttribute,
} from '@angular/core';
import { QTableCellDensity } from '../../types/table-cell-density.type';
import { QTableCellVariant } from '../../types/table-cell-variant.type';

@Component({
  selector: 'td[q-table-cell]',
  imports: [NgSwitch, NgSwitchCase],
  templateUrl: './table-data-cell.component.html',
  styleUrls: ['./table-data-cell.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
})
export class QTableDataCellComponent {
  @Input({ transform: booleanAttribute }) @HostBinding('class.q-table-cell-is-number') isNumber =
    false;
  @Input() variant: QTableCellVariant = 'default';
  @Input() density: QTableCellDensity = 'medium';
  @Input({ transform: booleanAttribute }) @HostBinding('class.q-table-cell-centered') centered =
    false;
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-table-cell';

  @HostBinding('class') get hostClasses(): string {
    return ['q-table-cell', `q-table-cell-${this.density}`, `q-table-cell-${this.variant}`].join(
      ' ',
    );
  }
}
